types.definition:
export interface TreeNode {
  /** 节点的稳定值。 */
  value: string
  /** 展示给用户的节点文本。 */
  label: React.ReactNode
  /** 嵌套的子节点。 */
  children?: TreeNode[]
  /** 禁止展开和选择此节点。 */
  disabled?: boolean
  /** 显示在标签前的自定义图标。 */
  icon?: React.ReactNode
}

